{"results": [{"id": "hp_doc_f16da2e882e7673304a1c2a2e95f5eb0963492e7ff98964498532d350b231366", "title": "Marius Tucă", "text": "Marius Tucă (born 29 July 1966, Caracal, Olt County, Romania) is a Romanian journalist and TV host.", "score": 16.8158}, {"id": "hp_doc_cc26722f780d76ec07132b5e6d9058f8c4e9d749266324d28bdb0d19de22f99a", "title": "Connor Hallisey", "text": "Connor Hallisey (born February 9, 1993) is an American soccer player who last played for Sporting Kansas City in Major League Soccer.", "score": 5.7321}, {"id": "hp_doc_1ee38ec4aed85eb0748355141e0f6a8bbd6495ddac5f0d1a7337f6ecb0d3907e", "title": "Kim Cattrall", "text": "Kim Victoria Cattrall ( ; born 21 August 1956) is an English-Canadian actress. She is known for her role as Samantha Jones in the HBO romantic comedy series, \"Sex and the City\" (1998–2004), for which she received five Emmy Award nominations and four Golden Globe Award nominations, winning the 2002 Golden Globe for Best Supporting Actress. She reprised the role in the films \"Sex and the City\" (2008) and \"Sex and the City 2\" (2010).", "score": 5.7135}], "remaining_searches": 2}
