{"results": [{"id": "hp_doc_14c3860bf2e8791bc66c8fc8c7ff17435332de29a415b9d0aa86965faf9eaeec", "title": "Adam Obidziński", "text": "Adam Obidziński (born 23 December 1929 in Warsaw, Poland; died 21 August 1985 in Warsaw, Poland) was a Polish engineer and scientist, and co-founder of Meteor project.", "score": 18.3057}, {"id": "hp_doc_04a8ae038651200b6d219ab7136ec352606172d273c65ebc9b2d6608aa1af417", "title": "Bemowo", "text": "Bemowo is a district of Warsaw located in the western part of the city. Its territory covers the western belt of the former district of Wola, which was incorporated to Warsaw in the year 1951. The name of the district derives from the surname of General Józef Bem.", "score": 16.4667}, {"id": "hp_doc_88a11ec22b7205eb0f63362bd4e4f37615aa5f4066568a810ca3a5e1d2e1a44a", "title": "Edward Jan Habich", "text": "Edward Jan Habich (Spanish: \"Eduardo de Habich\" ) (31 January 1835, Warsaw – 31 October 1909, Lima, Peru) was a Polish engineer and mathematician. In 1876, he founded the National University of Engineering (Spanish: \"Universidad Nacional de Ingeniería\" ), a renowned engineering school in Lima, Peru. He was a member of the Peruvian Geographic Society and an Honorary Citizen of Peru. In his native Poland he took part in the January Uprising against the Russian Empire in 1863.", "score": 14.5018}], "remaining_searches": 1}
