{"results": [{"id": "hp_doc_d23a87e0972230a7f5d858db3ffdc5ae3f9f648c8bd2855aed748faeae520322", "title": "Bradford", "text": "Bradford is in the Metropolitan Borough of the City of Bradford in West Yorkshire, England, in the foothills of the Pennines 8.6 mi west of Leeds, and 16 mi northwest of Wakefield. Bradford became a municipal borough in 1847, and received its charter as a city in 1897. Following local government reform in 1974, city status was bestowed upon the wider metropolitan borough.", "score": 27.3456}, {"id": "hp_doc_d6cd82e7eae6b4a8a407efb570d5aefbdab2fbae9350808d9ae5b9824cf37192", "title": "Municipal Borough of Richmond (Surrey)", "text": "The Municipal Borough of Richmond or Richmond Municipal Borough was a municipal borough in Surrey, England from 1890 to 1965.", "score": 23.2551}, {"id": "hp_doc_9672e2851c5812027fb56545c758a5efb8212f2a0e528bca31c99052516b0d68", "title": "Tipton Municipal Borough", "text": "Tipton Municipal Borough was a municipal borough centred on the town of Tipton, Staffordshire (now West Midlands), England. It was created in 1938, when the Tipton Urban District (formed in 1894) received borough status.", "score": 21.9704}], "remaining_searches": 1}
